 if(!['fixed','limit','maximum','legacy'].includes(mode))throw Error('Unknown number precision');
 const pattern=config.negativePattern==null?c.negativePattern:Number(config.negativePattern);
 if(!Number.isInteger(pattern)||pattern<0||pattern>4)throw Error('Negative number pattern must be from 0 to 4');
 let raw=String(value).trim();
 if(config.inputLocale&&typeof value!=='number'){const parts=new Intl.NumberFormat(config.inputLocale).formatToParts(12345.6),g=parts.find(p=>p.type==='group')?.value,d=parts.find(p=>p.type==='decimal')?.value;if(g)raw=raw.split(g).join('');if(d&&d!=='.')raw=raw.replace(d,'.');}
 const match=raw.match(/^([+-]?)(\d*\.?\d*)(?:[eE]([+-]?\d+))?$/);
 if(!match||!/[0-9]/.test(match[2]))throw Error('Enter a valid number');
 const split=match[2].split('.'),digits=(split[0]+(split[1]||'')).replace(/^0+/,'')||'0';
 let scale=(split[1]||'').length-Number(match[3]||0),amount=BigInt(digits);
 // Bound decimal work independently of exponent text, including underflow inputs.
 if(Math.abs(scale)>1000)throw Error('Number exponent is too large');
 if(scale<0){amount*=10n**BigInt(-scale);scale=0;}
 const places=mode==='maximum'?scale:Number(config.decimals??(mode==='legacy'?3:2));
 if(scale>places){const divisor=10n**BigInt(scale-places);amount=(amount+divisor/2n)/divisor;scale=places;}
 else if(mode==='fixed'&&scale<places){amount*=10n**BigInt(places-scale);scale=places;}
 let text=amount.toString().padStart(scale+1,'0'),whole=scale?text.slice(0,-scale):text,fraction=scale?text.slice(-scale):'';
 if(mode!=='fixed')fraction=fraction.replace(/0+$/,'');
 if(config.grouping!==false){let size=c.sizes[0],index=0,groups=[];while(size>0&&whole.length>size){groups.unshift(whole.slice(-size));whole=whole.slice(0,-size);if(index<c.sizes.length-1)size=c.sizes[++index];}groups.unshift(whole);whole=groups.join(c.group);}
 if(config.leadingZero===false&&whole==='0'&&fraction)whole='';
